sys_script_include.script:
var HolidayService = Class.create();
HolidayService.prototype = {
    initialize: function() {},
    /** @returns {{ok:boolean, holidays:Array, message:string}} - never throws */
    getHolidays: function(year, country) {
        var out = {
            ok: false,
            holidays: [],
            message: ''
        };
        year = parseInt(year, 10);
        country = String(country || '').toUpperCase();
        if (!(year >= 2000 && year <= 2100) || !/^[A-Z]{2}$/.test(country)) {
            out.message = 'Invalid year or country code.';
            return out;
        }
        try {
            var r = new sn_ws.RESTMessageV2('Nager Date API', 'getPublicHolidays');
            r.setStringParameterNoEscape('year', String(year));
            r.setStringParameterNoEscape('country', country);
            r.setHttpTimeout(8000); // 8 seconds
            var resp = r.execute();
            var code = resp.getStatusCode();
            if (code !== 200) {
                gs.warn('HolidayService: HTTP ' + code); // log status only, never the body or secrets
                out.message = 'The holiday service is unavailable right now.';
                return out;
            }
            var data = JSON.parse(resp.getBody());
            out.holidays = data.map(function(h) {
                return {
                    date: h.date,
                    name: h.name,
                    localName: h.localName
                };
            });
            out.ok = true;
            if (out.holidays.length === 0) {
                out.message = 'No holidays found for that year and country.';
            }
        } catch (e) {
            gs.warn('HolidayService error: ' + e.message);
            out.message = 'The holiday service is unavailable right now.';
        }
        return out;
    },
    type: 'HolidayService'
};
